import React, { useEffect, useRef } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

export default function TheSecondLayer() {
  const containerRef = useRef(null);
  const cardsRef = useRef([]);
  // Clear refs on re-render to avoid duplicates
  cardsRef.current = [];

  const addToRefs = (el) => {
    if (el && !cardsRef.current.includes(el)) {
      cardsRef.current.push(el);
    }
  };

  useEffect(() => {
    let ctx = gsap.context(() => {
      const cards = cardsRef.current;
      
      // Pin the entire section so it stays on screen while cards scroll
      ScrollTrigger.create({
        trigger: containerRef.current,
        start: "top top",
        end: `+=${cards.length * 900}`, // long scroll distance
        pin: true,
        pinSpacing: true,
      });

      cards.forEach((card, i) => {
        // Skip the very first card for entrance animation, it's already there
        if (i > 0) {
          gsap.fromTo(card, 
            { y: "150vh" }, // start hidden below
            {
              y: "0vh",   // slide up into view
              ease: "none",
              scrollTrigger: {
                trigger: containerRef.current,
                start: `top+=${i * 900 - 900} top`, 
                end: `top+=${i * 900} top`,
                scrub: true,
              }
            }
          );
        }

        // When the *next* card slides up over this one,
        // this card scales down, fades out slightly, and blurs.
        if (i < cards.length - 1) {
          gsap.to(card, {
            scale: 0.9,
            opacity: 0.4,
            filter: "blur(10px)",
            ease: "none",
            scrollTrigger: {
              trigger: containerRef.current,
              start: `top+=${(i + 1) * 900 - 900} top`,
              end: `top+=${(i + 1) * 900} top`,
              scrub: true,
            }
          });
        }
      });
    }, containerRef);
    
    return () => ctx.revert();
  }, []);

  const steps = [
    {
      time: "T-0:00",
      tag: "INSTANT CONFIRMATION",
      title: "Locking the Slot",
      desc: "Immediate WhatsApp dispatch securely locking the appointment in your HMS. The patient receives exact time, maps link, and practitioner details.",
      bg: "bg-obsidian border-obsidian",
      text: "text-white"
    },
    {
      time: "T-24:00",
      tag: "THE DAY PRIOR",
      title: "Predictive Nudge",
      desc: "Our algorithms identify high-risk no-show profiles, triggering personalized reminders specifically calibrated to confirm attendance.",
      bg: "bg-[#111111] border-[#222]",
      text: "text-white"
    },
    {
      time: "T-02:00",
      tag: "FINAL SYNC",
      title: "Friction Removal",
      desc: "A pre-visit contextual sync containing parking instructions and necessary intake documents, eliminating last-minute patient friction.",
      bg: "bg-[#1C1C24] border-[#2D2D38]",
      text: "text-white"
    },
    {
      time: "T+00:15",
      tag: "IF NO-SHOW",
      title: "Immediate Recovery",
      desc: "If a patient misses their slot, a silent multi-touch sequence attempts to reschedule them immediately before the lead goes cold.",
      bg: "bg-brand border-brand/50",
      text: "text-white"
    }
  ];

  return (
    <section className="bg-[#FAF8F5] relative overflow-hidden h-screen flex flex-col justify-center" ref={containerRef}>
      
      {/* Background Section Title Header */}
      <div className="absolute top-8 md:top-16 left-0 right-0 px-6 md:px-12 lg:px-20 z-0 opacity-40">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
          <h2 className="font-sans text-5xl md:text-7xl font-bold text-obsidian tracking-tighter leading-[0.9]">
            The call recovers.<br />
            <span className="serif-hero font-light italic">WhatsApp retains.</span>
          </h2>
          <p className="font-mono text-xs uppercase tracking-widest font-bold max-w-xs text-right hidden md:block">
            04 Step background <br/>retention protocol
          </p>
        </div>
      </div>

      <div className="absolute inset-0 z-10 w-full h-full flex items-center justify-center px-4 md:px-12 pt-24 md:pt-[15vh]">
        <div className="w-full max-w-4xl h-[70vh] md:h-[65vh] relative perspective-[1000px]">
          
          {steps.map((step, i) => (
            <div 
              key={i} 
              ref={addToRefs}
              className={`absolute top-0 left-0 w-full h-full rounded-[2.5rem] md:rounded-[3rem] p-8 md:p-16 flex flex-col justify-between shadow-2xl border ${step.bg} ${step.text} will-change-transform origin-top`}
              style={{ zIndex: i }}
            >
              
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 border-b border-white/10 pb-8">
                <span className="font-mono text-[11px] md:text-xs uppercase tracking-[0.2em] font-bold opacity-80 border border-white/20 px-4 py-2 rounded-full">
                  {step.tag}
                </span>
                <span className="font-mono text-[2.5rem] md:text-[4rem] font-bold tabular-nums tracking-tighter opacity-90 leading-none">
                  {step.time}
                </span>
              </div>

              <div className="mt-auto">
                <h3 className="font-sans text-4xl md:text-5xl lg:text-[4rem] font-bold tracking-tighter mb-4 leading-[1.05]">
                  {step.title}
                </h3>
                <p className="text-lg md:text-xl opacity-70 leading-relaxed max-w-2xl font-medium">
                  {step.desc}
                </p>
              </div>

            </div>
          ))}

        </div>
      </div>
    </section>
  );
}

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

const vertexShader = `
  uniform float uTime;
  uniform float uDistortion;
  uniform float uSize;
  uniform vec2 uMouse;
  varying float vNoise;

  // Simplex Noise
  vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
  vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
  vec4 permute(vec4 x) { return mod289(((x*34.0)+1.0)*x); }
  vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

  float snoise(vec3 v) {
      const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
      const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);
      vec3 i  = floor(v + dot(v, C.yyy) );
      vec3 x0 = v - i + dot(i, C.xxx) ;
      vec3 g = step(x0.yzx, x0.xyz);
      vec3 l = 1.0 - g;
      vec3 i1 = min( g.xyz, l.zxy );
      vec3 i2 = max( g.xyz, l.zxy );
      vec3 x1 = x0 - i1 + 1.0 * C.xxx;
      vec3 x2 = x0 - i2 + 2.0 * C.xxx;
      vec3 x3 = x0 - 1.0 + 3.0 * C.xxx;
      i = mod289(i);
      vec4 p = permute( permute( permute(
                  i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
              + i.y + vec4(0.0, i1.y, i2.y, 1.0 ))
              + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));
      float n_ = 1.0/7.0;
      vec3  ns = n_ * D.wyz - D.xzx;
      vec4 j = p - 49.0 * floor(p * ns.z *ns.z);
      vec4 x_ = floor(j * ns.z);
      vec4 y_ = floor(j - 7.0 * x_ );
      vec4 x = x_ *ns.x + ns.yyyy;
      vec4 y = y_ *ns.x + ns.yyyy;
      vec4 h = 1.0 - abs(x) - abs(y);
      vec4 b0 = vec4( x.xy, y.xy );
      vec4 b1 = vec4( x.zw, y.zw );
      vec4 s0 = floor(b0)*2.0 + 1.0;
      vec4 s1 = floor(b1)*2.0 + 1.0;
      vec4 sh = -step(h, vec4(0.0));
      vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
      vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;
      vec3 p0 = vec3(a0.xy,h.x);
      vec3 p1 = vec3(a0.zw,h.y);
      vec3 p2 = vec3(a1.xy,h.z);
      vec3 p3 = vec3(a1.zw,h.w);
      vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
      p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
      vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
      m = m * m;
      return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3) ) );
  }

  void main() {
      vec3 pos = position;
      float noise = snoise(vec3(pos.x * 0.3 + uTime * 0.5, pos.y * 0.3 + uTime * 0.5, pos.z * 0.3));
      vNoise = noise;
      vec3 direction = normalize(pos);
      vec3 newPos = pos + (direction * noise * uDistortion);
      float dist = distance(uMouse * 10.0, newPos.xy);
      float interaction = smoothstep(6.0, 0.0, dist);
      newPos.z += interaction * 1.5;
      vec4 mvPosition = modelViewMatrix * vec4(newPos, 1.0);
      gl_Position = projectionMatrix * mvPosition;
      gl_PointSize = uSize * (20.0 / -mvPosition.z);
  }
`;

const fragmentShader = `
  uniform vec3 uColor;
  varying float vNoise;
  void main() {
      vec2 center = gl_PointCoord - vec2(0.5);
      float dist = length(center);
      if (dist > 0.45) discard;
      float alpha = 1.0;
      vec3 color1 = uColor;
      vec3 color2 = vec3(0.25, 0.35, 0.45);
      vec3 finalColor = mix(color1, color2, vNoise * 0.5 + 0.5);
      gl_FragColor = vec4(finalColor, alpha);
  }
`;

export default function ThreeBackground() {
  const mountRef = useRef(null);

  useEffect(() => {
    if (!mountRef.current) return;

    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0xF5F5F7, 0.04);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 0, 20);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const objectGroup = new THREE.Group();
    scene.add(objectGroup);

    const geometry = new THREE.IcosahedronGeometry(6, 32);
    const uniforms = {
        uTime: { value: 0 },
        uDistortion: { value: 1.5 },
        uSize: { value: 2.0 },
        uColor: { value: new THREE.Color('#084DF2') },
        uMouse: { value: new THREE.Vector2(0, 0) }
    };

    const material = new THREE.ShaderMaterial({
        vertexShader,
        fragmentShader,
        uniforms: uniforms,
        transparent: true,
        blending: THREE.NormalBlending
    });

    const points = new THREE.Points(geometry, material);
    objectGroup.add(points);

    let mouseX = 0, mouseY = 0;
    let frameId;
    const clock = new THREE.Clock();

    const handleMouseMove = (e) => {
        mouseX = (e.clientX / window.innerWidth) * 2 - 1;
        mouseY = -(e.clientY / window.innerHeight) * 2 + 1;
    };

    const adjustLayout = () => {
        const w = window.innerWidth;
        if(w < 1024) {
            objectGroup.position.set(4, 5, -8);
            objectGroup.scale.set(0.65, 0.65, 0.65);
        } else {
            objectGroup.position.set(0, 2.5, 0);
            objectGroup.scale.set(0.65, 0.65, 0.65);
        }
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    };

    const handleScroll = () => {
        const scrollY = window.scrollY;
        objectGroup.rotation.z = scrollY * 0.0005;
        const w = window.innerWidth;
        const baseY = w < 1024 ? 5 : 2.5;
        objectGroup.position.y = baseY + scrollY * 0.005;
    };

    document.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('resize', adjustLayout);
    window.addEventListener('scroll', handleScroll);

    adjustLayout();

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        try {
            const time = clock.getElapsedTime();
            
            // Continuous auto-rotation
            objectGroup.rotation.y = time * 0.25;
            objectGroup.rotation.z = time * 0.1;
            
            // Breathing scale and position drift
            const breath = 1.0 + Math.sin(time * 1.5) * 0.05;
            objectGroup.scale.set(0.65 * breath, 0.65 * breath, 0.65 * breath);
            
            // Base Y position responds to scroll but also naturally floats
            const baseY = window.innerWidth < 1024 ? 5 : 2.5;
            objectGroup.position.y = baseY + Math.sin(time) * 0.3 + window.scrollY * 0.005;

            // Shader time and distortion pulsing
            uniforms.uTime.value = time;
            uniforms.uDistortion.value = 1.5 + Math.sin(time * 2.0) * 0.3;
            
            // If mouse is idle (0,0), use an automatic roaming target for the camera/shader
            const autoX = Math.sin(time * 0.5) * 0.5;
            const autoY = Math.cos(time * 0.4) * 0.5;
            const targetX = (mouseX === 0 && mouseY === 0) ? autoX : mouseX;
            const targetY = (mouseX === 0 && mouseY === 0) ? autoY : mouseY;
            
            uniforms.uMouse.value.x += (targetX - uniforms.uMouse.value.x) * 0.05;
            uniforms.uMouse.value.y += (targetY - uniforms.uMouse.value.y) * 0.05;
            
            camera.position.x += (targetX * 2.0 - camera.position.x) * 0.02;
            camera.position.y += (targetY * 2.0 - camera.position.y) * 0.02;
            camera.lookAt(0, 0, 0);
            
            renderer.render(scene, camera);
        } catch (e) {
            console.error("Three.js Animation Error:", e);
        }
    };

    animate();

    return () => {
      cancelAnimationFrame(frameId);
      document.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('resize', adjustLayout);
      window.removeEventListener('scroll', handleScroll);
      if (mountRef.current) {
        mountRef.current.removeChild(renderer.domElement);
      }
      geometry.dispose();
      material.dispose();
      renderer.dispose();
    };
  }, []);

  return <div ref={mountRef} className="fixed inset-0 z-0 opacity-100 pointer-events-none" />;
}

